INSERT INTO `categories` VALUES (3,'Software Development',NULL,'💻',1,0,'software-development','We specialize in custom software development and website design for construction companies, helping contractors, builders, architects, and infrastructure firms streamline operations and grow their business online.','We design and build robust software products — from MVPs to mission-critical enterprise systems. Modern stacks, clean code, and a relentless focus on shipping what users need.',NULL,'Software Development Services | LEAMSOFT','Custom web, mobile, and enterprise software built to scale.','software development, leamsoft, it services',1,3,'2026-07-28 16:46:07','2026-07-28 16:46:07','#00b4ff','uploads/categories/WiSrwzq6j3fr7iMWH3uGAHIY8du7fghCVKv2Oz98.jpg',0),(4,'AI & Machine Learning',NULL,'🤖',1,0,'ai-machine-learning','Custom AI models and LLM integrations that transform how you operate.','From predictive analytics to LLM-powered assistants and computer vision pipelines — we build AI that solves real business problems.',NULL,'AI & Machine Learning Services | LEAMSOFT','Custom AI models and LLM integrations that transform how you operate.','ai & machine learning, leamsoft, it services',1,3,'2026-07-27 03:36:02','2026-07-27 03:36:02','#a855f7','uploads/categories/azxZvcDPq7G5DXHbV2iVhGjH6ldjJmfW3AeGIwOL.jpg',1),(5,'Cloud Solutions',NULL,'☁️',1,0,'cloud-solutions','AWS, Azure & GCP expertise for the modern enterprise.','We architect, migrate, and manage cloud infrastructure that is secure, cost-effective, and built for scale.',NULL,'Cloud Solutions Services | LEAMSOFT','AWS, Azure & GCP expertise for the modern enterprise.','cloud solutions, leamsoft, it services',1,3,'2026-07-27 03:44:29','2026-07-27 03:44:29','#39d353','uploads/categories/jB8rlzKcSfMrQkAqrex1VObFYwiqoAjd8V8vTCdA.jpg',2),(6,'Cyber Security',NULL,'🛡️',1,0,'cyber-security','Enterprise security from pen testing to compliance.','End-to-end cyber security services that protect your business, your data, and your reputation.',NULL,'Cyber Security Services | LEAMSOFT','Enterprise security from pen testing to compliance.','cyber security, leamsoft, it services',1,3,'2026-07-27 05:14:41','2026-07-27 05:14:41','#ff3b5c','uploads/categories/eaq8Ubz1jBbWuJMkr64TUgCI2Zjo7DNPp6kQBZNb.jpg',3),(7,'Digital Marketing',NULL,'📈',1,0,'digital-marketing','Data-driven growth marketing that compounds.','SEO, paid campaigns, content, and analytics that grow brands beyond vanity metrics.',NULL,'Digital Marketing Services | LEAMSOFT','Data-driven growth marketing that compounds.','digital marketing, leamsoft, it services',1,3,'2026-07-27 05:17:15','2026-07-27 05:17:15','#ff8c00','uploads/categories/GRvrcqXiY08eYwoEdxHmdmeekIXF18NSUNrZikJW.jpg',4),(8,'IT Consulting',NULL,'💼',1,0,'it-consulting','Strategic technology advisory aligned to business outcomes.','Strategic guidance from leaders who have shipped at scale — from technology roadmaps to team augmentation.',NULL,'IT Consulting Services | LEAMSOFT','Strategic technology advisory aligned to business outcomes.','it consulting, leamsoft, it services',1,3,'2026-07-27 06:11:58','2026-07-27 06:11:58','#ffd700','uploads/categories/3H0WNXWGRKhDffJ20dVyRX7anxpS7rMrILnH6zml.jpg',5);
