INSERT INTO `clients` VALUES (1,'Gagandeep rajput','Founder & Managing Director','Eshan Buildwell India','https://eshanbuildwell.com/','uploads/clients/deD3tP5CCtW1egdwv6mdzx27ini3eSxc9ID53eR5.jpg','Eshan Buildwell India','Eshan Buildwell India is a construction and project management firm committed to delivering residential, commercial, and industrial projects with clarity, discipline, and cost efficiency.',0,0,1,3,'2026-08-18 07:34:54','2026-08-18 07:35:49'),(2,'Kundan Kumar','Founder','M Plus Academy','https://mplusacademy.com/','uploads/clients/R9OKWdzQ9J5dpo5TNmQMssX5xl6NXWM6VwD1Fta6.png','M Plus Academy','Great experience with Leamsoft! Professional team, smooth communication, and excellent website development. Highly recommended for reliable digital solutions.',1,1,1,3,'2026-10-07 05:21:55','2026-10-07 05:21:55'),(3,'Nishant Sharma','Founder & Managing Director','Parkly Inc','https://parkly.leamsoft.com/','uploads/clients/BSKCxqfinCzHVwacRcPo97Q69cV72O681RQuQrnc.png','Parkly Inc','Excellent work by Leamsoft on the matching engine. The system is fast, accurate, and efficiently matches parking spaces with user requirements. Great technical execution and highly recommended!',2,1,1,3,'2026-10-07 05:34:49','2026-10-07 05:36:29'),(4,'Aditya Sahgal','Founder & Managing Director','One Qr Solutions','https://oneqr.leamsoft.com/','uploads/clients/akB6FKSZaqzkWHDaB0Z5kwUUWSr5cxad59EYACac.webp','One QR code Infinite destinations','Leamsoft did an excellent job building ONEQR. The platform made it easy to create and manage dynamic QR codes while giving us real-time scan insights. The ability to update destinations without reprinting has made QR campaigns much more efficient.',3,1,1,3,'2026-10-07 05:40:28','2026-10-07 05:40:28');
