  `phone` varchar(100) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `facebook` varchar(1000) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
